WITH scored AS (SELECT *, ROUND(age / SUM(age) OVER (PARTITION BY city), 4) age_share, LAST_VALUE(age, TRUE) OVER (PARTITION BY segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_age, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY country, city), 4) credit_limit_share FROM customers) SELECT CASE WHEN credit_limit_share >= 0.86 THEN 'HIGH' ELSE 'LOW' END AS credit_limit_share_tier, COUNT(*) FILTER (WHERE segment = 'Consumer') AS consumer_rows, COUNT(*) AS event_count FROM scored GROUP BY CUBE (CASE WHEN credit_limit_share >= 0.86 THEN 'HIGH' ELSE 'LOW' END);
